import numpy as np


def mse(pred, target):
    return np.mean((pred - target) ** 2)


# Synthetic house prices: 5 features, a known linear rule plus a little noise
rng = np.random.default_rng(0)
X = rng.standard_normal((120, 5))
true_w = np.array([3.0, -2.0, 0.5, 1.5, 4.0])
y = X @ true_w + 10.0 + 0.1 * rng.standard_normal(120)
X_train, y_train, X_val, y_val = X[:100], y[:100], X[100:], y[100:]


def iterate_minibatches(X, y, batch_size):
    for start in range(0, len(X), batch_size):
        yield X[start:start + batch_size], y[start:start + batch_size]


def train(X_train, y_train, X_val, y_val, epochs=50, lr=0.05, batch_size=16):
    w = np.zeros(X_train.shape[1])
    b = 0.0
    history = []
    for epoch in range(epochs):
        for Xb, yb in iterate_minibatches(X_train, y_train, batch_size):
            err = Xb @ w + b - yb
            w -= lr * 2 * Xb.T @ err / len(yb)
            b -= lr * 2 * err.mean()
        history.append((mse(X_train @ w + b, y_train), mse(X_val @ w + b, y_val)))
    return w, b, history


result = train(X_train, y_train, X_val, y_val)
if result is None:
    print("train() returned None")
else:
    w, b, history = result
    for epoch in (1, 10, 50):
        train_loss, val_loss = history[epoch - 1]
        print(f"Epoch {epoch}: train={train_loss:.4f} val={val_loss:.4f}")
    print("learned weights:", np.round(w, 2), "bias:", round(float(b), 2))
